//! Declarations of PHP's built-in functions, classes and constants.
//!
//! `stubs/builtins.php` is generated by reflection from a PHP installation
//! (declarations only, no bodies) and embedded in the binary. Indexing it lets
//! resolution, hover and completion cover `strlen`, `Exception` and friends,
//! and makes "undefined symbol" inspections safe to report.

use std::path::PathBuf;

/// The generated stub source.
pub const BUILTINS_SOURCE: &str = include_str!("../../stubs/builtins.php");

/// Where the stub file lives on disk, so go-to-declaration can open it.
///
/// It sits in the system temp directory, versioned by crate version so an
/// upgrade never reads stale declarations.
pub fn builtins_path() -> PathBuf {
    std::env::temp_dir()
        .join("phpthunder")
        .join(format!("builtins-{}.php", env!("CARGO_PKG_VERSION")))
}

/// Writes the stub file to [`builtins_path`] unless it is already there with the
/// same content, and returns the path. Called before indexing a project.
///
/// # Errors
/// Returns the I/O error when the directory or file cannot be written.
pub fn write_builtins() -> std::io::Result<PathBuf> {
    let path = builtins_path();
    let current = std::fs::read_to_string(&path).ok();
    if current.as_deref() != Some(BUILTINS_SOURCE) {
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir)?;
        }
        std::fs::write(&path, BUILTINS_SOURCE)?;
    }
    Ok(path)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::index::index_source;

    #[test]
    fn builtins_should_declare_core_symbols() {
        let entry = index_source(BUILTINS_SOURCE);
        let has = |name: &str| entry.symbols.iter().any(|s| s.fqn == name);
        assert!(
            has("strlen")
                && has("Exception")
                && has("ArrayIterator")
                && has("DateTimeImmutable")
                && has("hash_hmac")
                && has("random_int")
        );
    }
}
